    sort(arr.begin(), arr.end()); 

    for (int i = 0; i < arr.size() - 1; i++) {

        // If the adjacent elements are equal
        if (arr[i] == arr[i + 1]) {
            return arr[i];
        }
    }
    return -1;
}

