    static int findDuplicate(int[] arr) {
        int n = arr.length;

        // Use long to avoid overflow
        long sum = 0;
        for (int num : arr) {
            sum += num;
        }

        // Expected sum of numbers from 1 to n-1
        long expectedSum = (long)(n - 1) * (n - 1 + 1) / 2;

        return (int)(sum - expectedSum);
}


